private const val COLLAPSED_EVENT_COUNT = 7

/**
 * `context_vault.event_log`, grouped as "last 30 days" -- the summary line above the individual
 * entries is `context_vault.thirty_day_trend_timeline`, a narrative recap of the same window.
 * Each entry's pill color comes from its own `direction` (BULLISH/BEARISH/NEUTRAL), not `kind` --
 * `kind` is just the short category label shown inside the pill (e.g. "RSI", "52W_HIGH").
 *
 * 2026-09-06: collapsed by default -- same tap-to-expand header, `BringIntoViewRequester`, and
 * hand-rolled (not [com.marketlabs.pulse.ui.screens.stocks.detail.DataCardSectionHeader]) title
 * row [ResolvedCallsSection] uses, since that shared header has no chevron/click affordance.
 * Once expanded, shows its latest 7 -- sorted newest-first (`event.date` is an ISO `yyyy-MM-dd`
 * string, so a plain descending string sort already orders it correctly) rather than relying on
 * the backend's already-chronological (oldest-first) order and reading the tail as "latest" --
 * with a [ViewMoreRow] pushing to a new screen with the full sorted list when there are more than 7.
 */
@Composable
fun EventLog(contextVault: DomainContextVault?, onViewMore: () -> Unit = {}, modifier: Modifier = Modifier) {
    val sortedEvents = contextVault?.eventLog.orEmpty().sortedByDescending { it.date ?: "" }
    if (sortedEvents.isEmpty() && contextVault?.thirtyDayTrendTimeline == null) return

    var expanded by remember { mutableStateOf(false) }
    val bringIntoViewRequester = remember { BringIntoViewRequester() }
    val coroutineScope = rememberCoroutineScope()
    val pulseColors = LocalPulseColors.current
    val visibleEvents = sortedEvents.take(COLLAPSED_EVENT_COUNT)

    PulseCard(style = PulseCardStyle.DATA, modifier = modifier.fillMaxWidth()) {
        Column {
            Column(
                modifier = Modifier
                    .fillMaxWidth()
                    .bringIntoViewRequester(bringIntoViewRequester)
                    .clickable {
                        val wasExpanded = expanded
                        expanded = !expanded
                        if (wasExpanded) {
                            coroutineScope.launch { bringIntoViewRequester.bringIntoView() }
                        }
                    }
                    .padding(dimensionResource(id = R.dimen.padding_large))
            ) {
                Row(verticalAlignment = Alignment.CenterVertically) {
                    Text(
                        text = stringResource(id = R.string.stock_detail_technical_timeline_title),
                        style = MaterialTheme.typography.titleSmall.copy(fontWeight = FontWeight.Bold),
                        color = MaterialTheme.colorScheme.primary,
                        modifier = Modifier.weight(1f, fill = false)
                    )
                    Icon(
                        painter = painterResource(id = if (expanded) R.drawable.ic_arrow_up else R.drawable.ic_arrow_down),
                        contentDescription = null,
                        tint = pulseColors.accentPrimary,
                        modifier = Modifier
                            .padding(start = dimensionResource(id = R.dimen.padding_medium))
                            .size(dimensionResource(id = R.dimen.icon_size_small))
                    )
                }
                androidx.compose.foundation.layout.Spacer(modifier = Modifier.height(dimensionResource(id = R.dimen.padding_tiny)))
                Text(
                    text = stringResource(id = R.string.stock_detail_technical_timeline_subtitle),
                    style = MaterialTheme.typography.labelMedium,
                    color = pulseColors.onSurfaceMuted
                )
            }

            if (expanded) {
                HorizontalDivider(
                    color = MaterialTheme.colorScheme.onSurface.copy(alpha = 0.1f),
                    thickness = dimensionResource(id = R.dimen.border_thin)
                )

                Column(modifier = Modifier.padding(dimensionResource(id = R.dimen.padding_large))) {
                    contextVault?.thirtyDayTrendTimeline?.let {
                        // 💡 onSurface, not onSurfaceMuted -- a full analytical sentence reads as
                        // this app's normal body-text color everywhere else on the Detail screen.
                        Text(text = it, style = MaterialTheme.typography.bodyMedium, color = MaterialTheme.colorScheme.onSurface)
                        Spacer()
                    }

                    visibleEvents.forEachIndexed { index, event ->
                        EventRow(event)
                        if (index != visibleEvents.lastIndex) {
                            HorizontalDivider(
                                color = MaterialTheme.colorScheme.onSurface.copy(alpha = 0.1f),
                                thickness = dimensionResource(id = R.dimen.border_thin),
                                modifier = Modifier.padding(vertical = dimensionResource(id = R.dimen.padding_medium))
                            )
                        }
                    }

                    if (sortedEvents.size > COLLAPSED_EVENT_COUNT) {
                        Spacer()
                        ViewMoreRow(text = stringResource(id = R.string.stock_detail_view_more), onClick = onViewMore)
                    }
                }
            }
        }
    }
}

/**
 * `date` + `kind` pill share a line (a short date and a short label always fit comfortably); the
 * event's own `text` goes on its own full-width line below rather than continuing that same row --
 * with a date column, a pill, and body text all competing for one row, the description's leftover
 * space shrank to whatever the date+pill didn't use, which is what was making it wrap awkwardly/
 * overflow on longer entries. `event.date` comes over the wire as an ISO `yyyy-MM-dd` string (e.g.
 * "2026-07-28"); `toLongDateString()` renders that as "July 28" instead.
 */
@Composable
fun EventRow(event: DomainEventLogItem) {
    val pulseColors = LocalPulseColors.current
    val (pillColor, textColor) = when (event.direction?.uppercase(Locale.US)) {
        "BULLISH" -> pulseColors.signalBullishPill to pulseColors.signalBullishText
        "BEARISH" -> pulseColors.signalBearishPill to pulseColors.signalBearishText
        else -> pulseColors.signalNeutralPill to pulseColors.signalNeutralText
    }

    Column {
        Row(verticalAlignment = Alignment.CenterVertically) {
            event.date?.let {
                Text(
                    text = it.toLongDateString(),
                    style = MaterialTheme.typography.labelSmall,
                    color = pulseColors.onSurfaceMuted
                )
                androidx.compose.foundation.layout.Spacer(modifier = Modifier.width(dimensionResource(id = R.dimen.padding_medium)))
            }
            event.kind?.let {
                SignalPill(text = it.replace('_', ' ').uppercase(Locale.US), pillColor = pillColor, contentColor = textColor)
            }
        }
        event.text?.let {
            androidx.compose.foundation.layout.Spacer(modifier = Modifier.height(dimensionResource(id = R.dimen.padding_small)))
            Text(
                text = it,
                style = MaterialTheme.typography.bodyMedium,
                color = MaterialTheme.colorScheme.onSurface,
                modifier = Modifier.fillMaxWidth()
            )
        }
    }
}

@Composable
private fun Spacer() {
    androidx.compose.foundation.layout.Spacer(modifier = Modifier.height(dimensionResource(id = R.dimen.padding_medium)))
}

